-- ── SPEC 066 STAGE 3b (d) · Wander Development ─────────────────────────────
-- Generated by scripts/stage3-move-sql.js from e88119ac-SMP-working-copy-Q3-Review-2026-10-18-1730.html
-- on 2026-10-18 15:13 UTC. Do not edit by hand:
-- regenerate it, so what runs is what the product's own capFoldPlan() says.
--
-- WHAT IT DOES: the 3 capability records become 4 internal pillars of the
-- Wander Development company's own plan, and the company is set to show its pillars apart
-- so the two tabs people read today do not move.
--
--   CODE          NAME                                     OWNER AFTER       ROW ID
--   C001.1 → C001 Data analysis and dashboard              (none)             cap:cap1-P1
--   C001.2 → C002 FFP - Fit-For-purpose tools              Strategy Management Office cap:cap1-P2
--   C002 → C003   HIPOs Program & Talent Management        HR                 cap:cap2-P1
--   C003 → C004   Decision Making                          BD                 cap3-P1
--
-- Every row id is kept, so every figure, snapshot, submitted report and
-- history entry still points at the row it pointed at.
--
-- HOW TO RUN IT: paste the whole file into Neon's SQL editor and run it once.
-- It is ONE transaction with its preconditions asserted inside: if the database
-- is not in the state this was generated for, it raises and rolls everything
-- back, changing nothing. Running it twice is refused by the same guards.

-- 0 · WHICH CLIENT IS WHICH? Run this first, on its own. It only reads, and
--     it makes the database name itself rather than asking you to know. The
--     row to look for is Wander Development with 4 capabilities.
--
-- SELECT t.key, t.name, t.status,
--        (SELECT count(*) FROM smp.capabilities c WHERE c.tenant_id = t.id) AS capabilities,
--        (SELECT o.org_name FROM smp.org o WHERE o.tenant_id = t.id)        AS "name inside"
--   FROM smp.tenants t ORDER BY t.name;

BEGIN;

-- 1 · THE PRECONDITIONS, BEFORE ANYTHING ELSE. Each raises, which rolls the
--     whole transaction back. They come first so that a second run says what is
--     actually wrong rather than tripping over a backup table it made before.
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM smp.tenants WHERE key = 'wander-development';
  IF n <> 1 THEN RAISE EXCEPTION 'no client with the key wander-development'; END IF;
  -- the rows really are the client this file was generated from
  SELECT count(*) INTO n FROM smp.org WHERE tenant_id = (SELECT id FROM smp.tenants WHERE key = 'wander-development') AND org_name = 'Wander Development';
  IF n <> 1 THEN RAISE EXCEPTION 'this is not Wander Development, which this file was generated for'; END IF;
  SELECT count(*) INTO n FROM smp.capabilities WHERE tenant_id = (SELECT id FROM smp.tenants WHERE key = 'wander-development') AND id IN ('cap1', 'cap2', 'cap3');
  IF n <> 3 THEN
    RAISE EXCEPTION 'expected 3 capabilities by id, found %', n; END IF;
  SELECT count(*) INTO n FROM smp.capabilities WHERE tenant_id = (SELECT id FROM smp.tenants WHERE key = 'wander-development');
  IF n <> 3 THEN
    RAISE EXCEPTION 'this client holds % capabilities, not the 3 this was generated for', n; END IF;
  SELECT jsonb_array_length(coalesce(extra->'items','[]'::jsonb)) INTO n FROM smp.capabilities WHERE tenant_id = (SELECT id FROM smp.tenants WHERE key = 'wander-development') AND id = 'cap1';
  IF n <> 2 THEN RAISE EXCEPTION 'Data Management holds % pillars, not the 2 this was generated for', n; END IF;
  SELECT jsonb_array_length(coalesce(extra->'items','[]'::jsonb)) INTO n FROM smp.capabilities WHERE tenant_id = (SELECT id FROM smp.tenants WHERE key = 'wander-development') AND id = 'cap2';
  IF n <> 1 THEN RAISE EXCEPTION 'Leadership and Development holds % pillars, not the 1 this was generated for', n; END IF;
  SELECT jsonb_array_length(coalesce(extra->'items','[]'::jsonb)) INTO n FROM smp.capabilities WHERE tenant_id = (SELECT id FROM smp.tenants WHERE key = 'wander-development') AND id = 'cap3';
  IF n <> 0 THEN RAISE EXCEPTION 'Decision Making holds % pillars, not the 0 this was generated for', n; END IF;
  SELECT count(*) INTO n FROM smp.cap_key_objectives WHERE tenant_id = (SELECT id FROM smp.tenants WHERE key = 'wander-development');
  IF n <> 0 THEN RAISE EXCEPTION '% capability objectives would be lost', n; END IF;
  SELECT count(*) INTO n FROM smp.projects WHERE tenant_id = (SELECT id FROM smp.tenants WHERE key = 'wander-development');
  IF n <> 1 THEN RAISE EXCEPTION '% capability projects, not the 1 this was generated for', n; END IF;
  -- Decision Making's project, and every row hanging off it
  SELECT count(*) INTO n FROM smp.projects WHERE tenant_id = (SELECT id FROM smp.tenants WHERE key = 'wander-development') AND id = 'cap3-P1' AND cap_id = 'cap3';
  IF n <> 1 THEN RAISE EXCEPTION 'the project cap3-P1 is not there'; END IF;
  SELECT count(*) INTO n FROM smp.deliverables WHERE project_id = 'cap3-P1';
  IF n <> 5 THEN RAISE EXCEPTION '% deliverables, not the 5 this was generated for', n; END IF;
  SELECT count(*) INTO n FROM smp.milestones WHERE project_id = 'cap3-P1';
  IF n <> 5 THEN RAISE EXCEPTION '% milestones, not the 5 this was generated for', n; END IF;
  SELECT count(*) INTO n FROM smp.outcomes WHERE project_id = 'cap3-P1';
  IF n <> 0 THEN RAISE EXCEPTION '% outcomes would be lost', n; END IF;
  SELECT count(*) INTO n FROM smp.milestones WHERE project_id = 'cap3-P1'
     AND (coalesce(covers,'') <> '' OR coalesce(finish,'') <> '' OR coalesce(status,'') <> ''
          OR pct IS NOT NULL OR coalesce(note,'') <> '');
  IF n <> 0 THEN RAISE EXCEPTION '% milestones carry a date, a state or a note, which this file does not translate', n; END IF;
  SELECT count(*) INTO n FROM smp.deliverables WHERE project_id = 'cap3-P1'
     AND (coalesce(status,'') <> '' OR pct IS NOT NULL OR coalesce(note,'') <> '' OR coalesce(due,'') <> '');
  IF n <> 0 THEN RAISE EXCEPTION '% deliverables carry a state, a date or a note, which this file does not translate', n; END IF;
  SELECT jsonb_array_length(coalesce(extra->'items','[]'::jsonb)) INTO n FROM smp.org WHERE tenant_id = (SELECT id FROM smp.tenants WHERE key = 'wander-development');
  IF n <> 0 THEN
    RAISE EXCEPTION 'the company plan holds % pillars, not the 0 this was generated for', n; END IF;
END $$;

-- 2 · A COPY OF THIS CLIENT'S ROWS IN BOTH TABLES, BEFORE ANYTHING CHANGES.
--     Keep them until the pages have been looked at; drop them after.
CREATE TABLE smp.org_before_20261018 AS SELECT * FROM smp.org WHERE tenant_id = (SELECT id FROM smp.tenants WHERE key = 'wander-development');
CREATE TABLE smp.capabilities_before_20261018 AS SELECT * FROM smp.capabilities WHERE tenant_id = (SELECT id FROM smp.tenants WHERE key = 'wander-development');

-- 3 · THE MOVE. Each new pillar is the row ALREADY IN THE DATABASE, with three
--     fields laid over it: the kind, the name where the inner pillar stores none,
--     and the owner where it stores none (a capability's seat holds a person's
--     key, a pillar's owner their name). No figure is retyped, because none is
--     read out and written back.
UPDATE smp.org o SET extra = jsonb_set(o.extra, '{items}', (o.extra->'items') || (
  SELECT coalesce(jsonb_agg(r.np ORDER BY r.ci, r.pi), '[]'::jsonb) FROM (
    -- a capability's inner pillars: the rows ALREADY IN THE DATABASE, with
    -- three fields laid over each — the kind, the name where the pillar
    -- stores none, and the owner where it stores none (a capability's seat
    -- holds a person's key, a pillar's owner their name).
    SELECT c.idx AS ci, el.ord AS pi,
           el.item
           || jsonb_build_object('kind', 'Capability')
           || jsonb_build_object('name', CASE
                WHEN coalesce(el.item->>'name','') <> '' THEN el.item->>'name'
                ELSE c.name END)
           || jsonb_build_object('owner', CASE
                WHEN coalesce(el.item->>'owner','') <> '' THEN el.item->>'owner'
                ELSE coalesce((SELECT p.name FROM smp.people p
                                WHERE p.key = c.extra->>'head' AND p.tenant_id = c.tenant_id), '') END) AS np
      FROM smp.capabilities c
      CROSS JOIN LATERAL jsonb_array_elements(coalesce(c.extra->'items','[]'::jsonb))
                         WITH ORDINALITY AS el(item, ord)
     WHERE c.tenant_id = o.tenant_id
    UNION ALL
    -- §544.7: and a capability that plans in a project becomes ONE pillar
    -- under the capability's own name, the project's id kept as the
    -- pillar's. Its DELIVERABLES are the key measures (they are targets)
    -- and its MILESTONES are the tactics (they are steps); every row keeps
    -- its own id. The target is left blank on purpose and no figure is
    -- written: the preconditions above have already refused any row that
    -- carries a date, a state or a note.
    SELECT c.idx AS ci, 0 AS pi,
           jsonb_build_object(
             'id', pr.id, 'code', '', 'sub', '', 'theme', '',
             'kind', 'Capability',
             'name', CASE WHEN coalesce(c.name,'') <> '' THEN c.name ELSE pr.name END,
             'owner', coalesce(pr.owner, ''),
             'measures', coalesce((
                SELECT jsonb_agg(jsonb_build_object(
                         'id', d.id, 'name', d.name, 'dir', '≥',
                         'target', '', 'compile', '',
                         'actual', NULL, 'progress', NULL) ORDER BY d.idx)
                  FROM smp.deliverables d WHERE d.project_id = pr.id), '[]'::jsonb),
             'tactics', coalesce((
                SELECT jsonb_agg(jsonb_build_object(
                         'id', m.id, 'name', m.name, 'owner', coalesce(m.owner,''),
                         'q1', 0, 'q2', 0, 'q3', 0, 'q4', 0,
                         'status', '', 'actual', NULL) ORDER BY m.idx)
                  FROM smp.milestones m WHERE m.project_id = pr.id), '[]'::jsonb)
           ) AS np
      FROM smp.projects pr
      JOIN smp.capabilities c ON c.id = pr.cap_id
     WHERE c.tenant_id = o.tenant_id
  ) r
)) WHERE o.tenant_id = (SELECT id FROM smp.tenants WHERE key = 'wander-development');

-- 4 · THE COMPANY SHOWS ITS PILLARS APART, so Directions and Capabilities
--     read as two tabs. Written defensively: the levels above the key are
--     created, because this client stores none of them yet.
--
--     §544.6: AND THE COMPANY HAS TO BE SHOWING A PLAN AT ALL. On a company
--     that never planned anything of its own — this one — the rows would
--     otherwise land stored and INVISIBLE: the top layer's plan starts off
--     (§428.2) and `pillar` is not among its components until it is ticked.
--     Measured in the rehearsal, where the Strategy tab went on reading
--     Foundation alone with four capabilities sitting behind it.
UPDATE smp.org SET extra =
  jsonb_set(
  jsonb_set(
  jsonb_set(
  jsonb_set(coalesce(extra, '{}'::jsonb),
    '{structure}',     coalesce(extra->'structure', '{}'::jsonb), true),
    '{structure,top}', coalesce(extra->'structure'->'top', '{}'::jsonb), true),
    '{structure,top,plan}',
        (coalesce(extra->'structure'->'top'->'plan', '{}'::jsonb) - 'on')
        || '{"split": true}'::jsonb, true),
    '{structure,top,on}', '["brief","purpose","aspiration","keyobj","theme","capability","values","pillar"]'::jsonb, true)
WHERE tenant_id = (SELECT id FROM smp.tenants WHERE key = 'wander-development');

-- 4b · AND WHERE THE CAPABILITIES LIVE, which is the office's own answer and
--      the reason this file was allowed to move records a function held
--      (§544.6). Written so the stored state ends up as the rehearsal left it.
UPDATE smp.org SET extra = jsonb_set(
  jsonb_set(coalesce(extra, '{}'::jsonb), '{structure}',
            coalesce(extra->'structure', '{}'::jsonb), true),
  '{structure,cap}',
  coalesce(extra->'structure'->'cap', '{}'::jsonb)
    || '{"at": "top", "exists": true}'::jsonb, true)
WHERE tenant_id = (SELECT id FROM smp.tenants WHERE key = 'wander-development');

-- 5 · THE RECORDS GO, now that every one of their pillars is in the list.
DELETE FROM smp.capabilities WHERE tenant_id = (SELECT id FROM smp.tenants WHERE key = 'wander-development') AND id IN ('cap1', 'cap2', 'cap3');

-- 6 · AND IT CHECKS ITS OWN WORK before it is allowed to commit.
DO $$
DECLARE n int; got text; want text;
BEGIN
  SELECT jsonb_array_length(extra->'items') INTO n FROM smp.org WHERE tenant_id = (SELECT id FROM smp.tenants WHERE key = 'wander-development');
  IF n <> 4 THEN
    RAISE EXCEPTION 'the company plan holds % pillars, expected 4', n; END IF;
  SELECT count(*) INTO n FROM smp.capabilities WHERE tenant_id = (SELECT id FROM smp.tenants WHERE key = 'wander-development');
  IF n <> 0 THEN RAISE EXCEPTION '% capability records are still there', n; END IF;
  SELECT (extra->'structure'->'top'->'plan'->>'split') INTO got FROM smp.org WHERE tenant_id = (SELECT id FROM smp.tenants WHERE key = 'wander-development');
  IF got IS DISTINCT FROM 'true' THEN
    RAISE EXCEPTION 'the company is not set to show its pillars apart (%)', got; END IF;
  SELECT string_agg(x.v, ' | ' ORDER BY x.i) INTO got FROM (
    SELECT ord AS i, (e->>'id') || '/' || (e->>'name') || '/' || coalesce(e->>'owner','') AS v
    FROM smp.org o, jsonb_array_elements(o.extra->'items') WITH ORDINALITY AS t(e, ord)
    WHERE o.tenant_id = (SELECT id FROM smp.tenants WHERE key = 'wander-development') AND e->>'kind' = 'Capability') x;
  want := 'cap:cap1-P1/Data analysis and dashboard/ | cap:cap1-P2/FFP - Fit-For-purpose tools/Strategy Management Office | cap:cap2-P1/HIPOs Program & Talent Management/HR | cap3-P1/Decision Making/BD';
  IF got IS DISTINCT FROM want THEN
    RAISE EXCEPTION 'the moved rows are not the ones planned. got: % want: %', got, want;
  END IF;
END $$;

COMMIT;

-- 7 · READ IT BACK. Run this after the commit; it changes nothing.
SELECT ord AS "#", e->>'kind' AS "kind", e->>'name' AS "name",
       e->>'owner' AS "owner", e->>'id' AS "row id",
       jsonb_array_length(coalesce(e->'measures','[]'::jsonb)) AS "measures",
       jsonb_array_length(coalesce(e->'tactics','[]'::jsonb))  AS "tactics"
  FROM smp.org o, jsonb_array_elements(o.extra->'items') WITH ORDINALITY AS t(e, ord)
 WHERE o.tenant_id = (SELECT id FROM smp.tenants WHERE key = 'wander-development') ORDER BY ord;
